/** An `Identity` (an input struct). */
export interface Identity {
  document: Text;
  /** A day from 1900-01-01 to 2100-12-31 (UTC); a moment in a day counts as that day. */
  born: Date;
  nationality: Country;
  netWorth: U64;
  /** A day from 1900-01-01 to 2100-12-31 (UTC); a moment in a day counts as that day. */
  expires: Date;
  salt: FieldInput;
}

/** A `Policy` (an input struct). */
export interface Policy {
  /** A day from 1900-01-01 to 2100-12-31 (UTC); a moment in a day counts as that day. */
  today: Date;
  /** A day from 1900-01-01 to 2100-12-31 (UTC); a moment in a day counts as that day. */
  bornBy: Date;
  minNetWorth: U64;
  /** A set of `Country`: one, or a list of them. */
  allowed: Country | readonly Country[];
}

/** Every input of `zkyc`. */
export interface ZkycInputs {
  id: Identity;
  commitment: FieldInput;
  policy: Policy;
}

/** The public inputs: what a verifier supplies, and what a proof reveals. */
export interface ZkycPublicInputs {
  commitment: FieldInput;
  policy: Policy;
}

/** A `Policy`, decoded, with its Rust methods. */
export class PolicyValue {
  today: Date;
  bornBy: Date;
  minNetWorth: bigint;
  allowed: Country[];

  constructor(v: {
    today: Date;
    bornBy: Date;
    minNetWorth: bigint;
    allowed: Country[];
  }) {
    this.today = v.today;
    this.bornBy = v.bornBy;
    this.minNetWorth = v.minNetWorth;
    this.allowed = v.allowed;
  }

  /**
   * Checked on `today`: the holder's document mustn't have expired by then.
   * (Written out rather than as `Day`: a client reads the type as written.)
   */
  on(today: Date): PolicyValue {
    return Policy.on(this, today);
  }

  /**
   * At least `years` old on `today` (set it with `on` first).
   */
  minAge(years: U16): PolicyValue {
    return Policy.minAge(this, years);
  }

  /**
   * A national of one of `allowed` (a country, or a list of them).
   */
  nationalities(allowed: Country | readonly Country[]): PolicyValue {
    return Policy.nationalities(this, allowed);
  }

  /**
   * Worth at least `amount`, in the attestor's unit.
   */
  worthAtLeast(amount: U64): PolicyValue {
    return Policy.worthAtLeast(this, amount);
  }
}

/** The public inputs, decoded from a proof. */
export interface ZkycPublicValues {
  commitment: Field;
  policy: PolicyValue;
}

/** The input structs, by name: what `fields` takes. */
export interface ZkycStructs {
  Identity: Identity;
  Policy: Policy;
}

/**
 * `zkyc`: make a prover or verifier from a URL serving a copy of
 * `target/xark/zkyc/` (relative to the page in a browser) or from the bytes:
 *
 * ```ts
 * const prover = await Zkyc.prover("/circuits/zkyc/");
 * const proof = prover.prove(inputs);
 * send(proof.toBytes()); // the proof; an exported Solana verifier reads it as is
 * const verifier = await Zkyc.verifier(vkBytes);
 * verifier.verify(bytes, publicInputs); // true: it proves the public inputs you require
 * ```
 */
export const Zkyc = new Circuit<ZkycInputs, ZkycPublicInputs, ZkycPublicValues, ZkycStructs>({
  name: "zkyc",
  schema,
  decodePublic,
  client: true,
  digest: "fdbbf1a8cc83d56cd35e46bca20d5eaf",
});

export type ZkycProver = Prover<ZkycInputs, ZkycPublicInputs, ZkycPublicValues, ZkycStructs>;
export type ZkycVerifier = Verifier<ZkycPublicInputs, ZkycPublicValues, ZkycStructs>;
export type ZkycProof = Proof<ZkycPublicValues>;

/** `Policy`'s Rust functions (`#[input] impl Policy`), run from `client.wasm`. */
export const Policy = {
  /**
   * Checked on `today`: the holder's document mustn't have expired by then.
   * (Written out rather than as `Day`: a client reads the type as written.)
   */
  on(policy: Policy, today: Date): PolicyValue {
    return decodePolicy(Zkyc.call<Json<PolicyValue>>("Policy.on", [policy, today]));
  },
  /**
   * A policy every holder passes: no expiry, age, net worth or nationality check.
   * Tighten it from there, starting with `on`.
   */
  default(): PolicyValue {
    return decodePolicy(Zkyc.call<Json<PolicyValue>>("Policy.default", []));
  },
  /**
   * At least `years` old on `today` (set it with `on` first).
   */
  minAge(policy: Policy, years: U16): PolicyValue {
    return decodePolicy(Zkyc.call<Json<PolicyValue>>("Policy.min_age", [policy, years]));
  },
  /**
   * A national of one of `allowed` (a country, or a list of them).
   */
  nationalities(policy: Policy, allowed: Country | readonly Country[]): PolicyValue {
    return decodePolicy(Zkyc.call<Json<PolicyValue>>("Policy.nationalities", [policy, allowed]));
  },
  /**
   * Worth at least `amount`, in the attestor's unit.
   */
  worthAtLeast(policy: Policy, amount: U64): PolicyValue {
    return decodePolicy(Zkyc.call<Json<PolicyValue>>("Policy.worth_at_least", [policy, amount]));
  },
};

/** `Identity`'s Rust functions (`#[input] impl Identity`), run from `client.wasm`. */
export const Identity = {
  /**
   * The issuer's commitment: Poseidon2 over every field, so adding one extends it.
   */
  commitment(identity: Identity): Field {
    return new Field(Zkyc.call<Json<Field>>("Identity.commitment", [identity]));
  },
};

function decodePublic(v: Json<ZkycPublicValues>): ZkycPublicValues {
  return {
    commitment: new Field(v.commitment),
    policy: decodePolicy(v.policy),
  };
}

function decodePolicy(v: Json<PolicyValue>): PolicyValue {
  return new PolicyValue({
    today: new Date(v.today),
    bornBy: new Date(v.bornBy),
    minNetWorth: BigInt(v.minNetWorth),
    allowed: v.allowed,
  });
}
